"use strict";(globalThis.webpackChunkgrc||=[]).push([[77306],{56690(e){e.exports=JSON.parse('{"citeKey":"li2009faultaware","slug":"li-2009-fault-aware-63af","title":"Fault-Aware Runtime Strategies for High Performance Computing","authors":["Y. Li","Z. Lan","P. Gujrati","X.-H. Sun"],"venue":"IEEE Transactions on Parallel and Distributed Systems, vol. 20, no. 4, pp. 460-473","type":"Journal","entryType":"article","date":"April, 2009","year":2009,"era":"iit","month":4,"doi":"10.1109/tpds.2008.128","abstract":"As the scale of parallel systems continues to grow, fault management of these systems is becoming a critical challenge. While existing research mainly focuses on developing or improving fault tolerance techniques, a number of key issues remain open. In this paper, we propose runtime strategies for spare node allocation and job rescheduling in response to failure prediction. These strategies, together with failure prediction and fault tolerance techniques, construct a runtime system called Fault-Aware Runtime System (FARS). In particular, we propose a 0-1 knapsack model and demonstrate its flexibility and effectiveness for reallocating running jobs to avoid failures. Experiments, by means of synthetic data and real traces from production systems, show that FARS has the potential to significantly improve system productivity (i.e., performance and reliability).","hasAbstract":true,"lede":"We propose runtime strategies for spare node allocation and job rescheduling in response to failure prediction.","links":{"pdf":"https://grc.iit.edu/papers/2009/li-2009-fault-aware-63af.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["fence"],"memberAuthors":["sun-xian-he"]}')}}]);